"use client"

import * as React from "react"

import { Button } from "@/components/ui/button"
import { Label } from "@/components/ui/label"
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover"
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group"
import { FALLBACK_VOICES } from "@/lib/mockups/add-voice-data"

export function FallbackVoicePicker({
  onValueChange,
  value,
}: {
  onValueChange: (voiceId: string) => void
  value: string
}) {
  const [open, setOpen] = React.useState(false)

  return (
    <Popover onOpenChange={setOpen} open={open}>
      <PopoverTrigger asChild>
        <Button variant="outline">Change voice</Button>
      </PopoverTrigger>

      <PopoverContent align="start" className="w-80">
        <RadioGroup
          className="gap-0"
          onValueChange={(voiceId) => {
            onValueChange(voiceId)
            setOpen(false)
          }}
          value={value}
        >
          {FALLBACK_VOICES.map((voice) => (
            <Label
              className="items-start gap-3 rounded-md px-2 py-1.5 font-normal transition-colors duration-150 hover:bg-accent motion-reduce:transition-none"
              htmlFor={`fallback-${voice.id}`}
              key={voice.id}
            >
              <RadioGroupItem
                className="mt-1"
                id={`fallback-${voice.id}`}
                value={voice.id}
              />
              <span className="flex flex-col gap-0.5">
                <span className="text-base font-medium">{voice.name}</span>
                <span className="text-muted-foreground">
                  {voice.vibe} · {voice.gender}
                </span>
              </span>
            </Label>
          ))}
        </RadioGroup>
      </PopoverContent>
    </Popover>
  )
}

import { InformationCircleIcon } from "@hugeicons/core-free-icons"

import { icon } from "@/components/shared/icon"

export const FieldHelpIcon = icon(InformationCircleIcon, "FieldHelpIcon")

"use client"

import { HugeiconsIcon, type IconSvgElement } from "@hugeicons/react"

/** No size of its own, so primitives size it through their `[&_svg]:size-4` rules. */
export function icon(glyph: IconSvgElement, displayName: string) {
  const Icon = (
    props: Omit<React.ComponentProps<typeof HugeiconsIcon>, "icon">,
  ) => <HugeiconsIcon icon={glyph} strokeWidth={1.8} {...props} />
  Icon.displayName = displayName
  return Icon
}

"use client"

import * as React from "react"
import Link from "next/link"

import { Button } from "@/components/ui/button"
import { BackIcon } from "@/components/shell/workspace-icons"

/** 48px tall: `AppShell` starts its fixed sidebar under it. */
export function MockupShell({
  title,
  actions,
  children,
}: {
  title: string
  /** Kept for the callers that pass it; the bar shows the title alone. */
  eyebrow?: string
  actions?: React.ReactNode
  children: React.ReactNode
}) {
  return (
    <div className="flex min-h-full grow flex-col bg-sidebar">
      <header className="sticky top-0 z-nav flex h-12 shrink-0 items-center gap-2 border-b bg-sidebar px-3">
        <Button aria-label="All mockups" asChild size="icon-sm" variant="ghost">
          <Link href="/">
            <BackIcon />
          </Link>
        </Button>
        <span
          className="min-w-0 flex-1 truncate text-sm font-medium"
          title={title}
        >
          {title}
        </span>
        {actions ? (
          <div className="flex shrink-0 items-center gap-1.5">{actions}</div>
        ) : null}
      </header>

      <div className="flex min-h-0 flex-1 flex-col">{children}</div>
    </div>
  )
}

